const STALE_THRESHOLD_MIN = 30;
const TS_FIELDS = ['created_at','createdAt','inserted_at','ts','timestamp'];
function extractRecords(body){if(Array.isArray(body))return body;if(body&&typeof body==='object'){for(const k of ['records','data','results','items'])if(Array.isArray(body[k]))return body[k];}return [];}
function extractNewestTs(body){let newest=null;for(const rec of extractRecords(body)){for(const f of TS_FIELDS){if(rec&&rec[f]!=null){const ms=Date.parse(rec[f]);if(!Number.isNaN(ms)&&(newest===null||ms>newest))newest=ms;break;}}}return newest;}
function classify(httpFailed,body,nowMs,thresholdMin){if(httpFailed)return 'down';const t=extractNewestTs(body);if(t===null)return 'stale';const ageMin=(nowMs-t)/60000;if(ageMin<0)return 'stale';return ageMin>thresholdMin?'stale':'ok';}
function decide(prev,current){const previous=prev||'ok';if(current===previous)return {alert:false,severity:null};if(current==='ok')return {alert:true,severity:'recovered'};return {alert:true,severity:current};}
function buildHeartbeatItem(o){const previous=o.prevState||'ok';const current=classify(o.httpFailed,o.body,o.nowMs,o.thresholdMin||STALE_THRESHOLD_MIN);const d=decide(previous,current);const newestMs=o.httpFailed?null:extractNewestTs(o.body);const ageMin=newestMs===null?null:Math.round((o.nowMs-newestMs)/60000);const nowIso=new Date(o.nowMs).toISOString();const nextSince=current===previous?(o.prevSince||nowIso):nowIso;let text=null;if(d.alert){if(d.severity==='down'){text='🔴 *Memory Mesh DOWN* — gateway /query unreachable (avm-02:8848). Last healthy: '+(o.prevSince||'unknown')+'.';}else if(d.severity==='stale'){const ageDisp=(ageMin==null||ageMin<0)?'?':ageMin;text='🟠 *Memory Mesh STALE* — newest record '+ageDisp+'m old (threshold '+(o.thresholdMin||STALE_THRESHOLD_MIN)+'m). Gateway up; ingest may have stopped.';}else{const dt=o.prevSince?Math.round((o.nowMs-Date.parse(o.prevSince))/60000)+'m':'unknown';text='✅ *Memory Mesh RECOVERED* — flow normal. Newest record '+(ageMin==null?'?':ageMin)+'m old. Downtime ≈ '+dt+'.';}}return {alert:d.alert,severity:d.severity,current:current,ageMin:ageMin,newestTs:newestMs===null?null:new Date(newestMs).toISOString(),text:text,nextState:current,nextSince:nextSince};}
const sd=$getWorkflowStaticData('global');
const prev=sd.meshHeartbeat||{};
const item=$input.first();
const httpFailed=!!(item.json&&item.json.error);
const out=buildHeartbeatItem({httpFailed:httpFailed,body:httpFailed?null:item.json,nowMs:Date.now(),prevState:prev.state||'ok',prevSince:prev.since||null});
sd.meshHeartbeat={state:out.nextState,since:out.nextSince,lastNewestTs:out.newestTs};
return [{json:{alert:out.alert,severity:out.severity,current:out.current,ageMin:out.ageMin,text:out.text}}];
